  function toast(O, t) { if (O && O.toast) return O.toast(t); var d = document.querySelector('.ef-toast'); if (d) d.remove(); d = document.createElement('div'); d.className = 'ef-toast'; d.textContent = t; document.body.appendChild(d); setTimeout(function () { d.remove() }, 3200) }
  function hap(O) { try { O && O.hap && O.hap() } catch (e) {} }
